// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;

    function setUp() public { c = new Owned(); }

    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));

        address admin = address(this);

        vm.prank(admin);
        bool ok1;
        try c.setOwner(caller) { ok1 = true; } catch { ok1 = false; }
        assertTrue(ok1);

        vm.prank(caller);
        bool ok2;
        try c.setOwner(newOwner) { ok2 = true; } catch { ok2 = false; }

        assertTrue(!ok2);
    }
}
